          kind: 'paragraph',
          runs: [
            { kind: 'text', text: 'NightTalesStudio ("we", "us", "the service") is a personal, owner-operated service that turns a story you approve into a narrated video episode and, when you ask it to, publishes that episode to a channel you have connected.' },
          ],
